import {CROPS,YEARS,compare,monthly,validateOptions} from './model.mjs';
const $=s=>document.querySelector(s),bnMonths=['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'],short=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
let raw,manifest,point,comparison=[],crops=CROPS.map(c=>({...c})),loadNumber=0;const cache=new Map();
const fmt=n=>n===null||n===undefined?'অসম্পূর্ণ':Math.round(n).toLocaleString('en-US');
$('#month').innerHTML=bnMonths.map((m,i)=>`<option value="${i+1}" ${i===10?'selected':''}>${m}</option>`).join('');
$('#detail-crop').innerHTML=CROPS.map(c=>`<option value="${c.id}">${c.bn}</option>`).join('');
$('#crop-inputs').innerHTML=CROPS.map(c=>`<tr><td>${c.bn}</td><td><input aria-label="${c.bn} সময় দিন" data-crop="${c.id}" data-field="days" type="number" min="30" max="240" value="${c.days}"></td><td><input aria-label="${c.bn} পানি mm" data-crop="${c.id}" data-field="need" type="number" min="100" max="1500" value="${c.need}"></td></tr>`).join('');
function options(){return {month:Number($('#month').value),day:Number($('#day').value),irrigation:Number($('#irrigation').value),soilWater:Number($('#soilWater').value),rainFraction:Number($('#rainFraction').value)/100,priority:$('#priority').value,soil:$('#soil').value,drainage:$('#drainage').value};}
async function load(){const token=++loadNumber;$('#status').textContent='NASA ডেটা পড়ছি…';$('#error').hidden=true;$('#result-body').hidden=true;$('#export').disabled=true;try{if(!manifest){const res=await fetch('data/manifest.json');if(!res.ok)throw Error('Manifest unavailable');manifest=await res.json();}const p=manifest.points.find(p=>p.id===$('#place').value);if(!p)throw Error('Unknown location');let data=cache.get(p.id);if(!data){const res=await fetch(p.file);if(!res.ok)throw Error('NASA archive unavailable');data=await res.json();if(!data.properties?.parameter?.PRECTOTCORR||!data.properties.parameter.T2M_MAX)throw Error('Invalid dataset');cache.set(p.id,data);}if(token!==loadNumber)return;point=p;raw=data;$('#point').textContent=`${p.lat.toFixed(2)}°N, ${p.lon.toFixed(2)}°E · জেলার একটি নমুনা বিন্দু`;$('#source-links').innerHTML=`<div class="source-row"><a href="${p.sourceUrl}" target="_blank" rel="noopener">${p.name}: মূল NASA POWER JSON</a><small>সংগ্রহ: ${p.retrievedAt.slice(0,10)} UTC · ${p.days} দৈনিক রেকর্ড · LST · ${p.header.api.version}</small><a href="${p.file}" download>সংরক্ষিত মূল ডেটা ডাউনলোড</a></div>`;$('#result-body').hidden=false;render();}catch(e){if(token!==loadNumber)return;$('#status').textContent='ডেটা পাওয়া যায়নি।';$('#error').hidden=false;$('#error p').textContent='সংরক্ষিত NASA ডেটা খুলতে সমস্যা হয়েছে। আবার চেষ্টা করুন। অনুমানভিত্তিক আবহাওয়া দেখাচ্ছি না।';console.error(e);}}
function render(){if(!raw)return;let o;try{o=options();validateOptions(o);comparison=compare(raw,crops,o);}catch(e){$('#status').textContent='ইনপুট ঠিক করুন: '+e.message;$('#result-body').hidden=true;$('#export').disabled=true;return;}$('#result-body').hidden=false;$('#export').disabled=false;$('#status').textContent=`${point.bn} · পাঁচ রোপণবর্ষ 2020–2024 · সংরক্ষিত বাস্তব NASA ডেটা`;$('#irrigation-label').textContent=`${o.irrigation} mm`;$('#fraction-label').textContent=`${Math.round(o.rainFraction*100)}%`;$('#season-label').textContent=`রোপণ: ${o.day} ${bnMonths[o.month-1]}`;
const notes=[];if(o.soil==='unknown')notes.push('মাটির ধরন অজানা।');else notes.push(`স্থানীয় মাটি: ${{loam:'দোআঁশ',clay:'এঁটেল',sand:'বেলে'}[o.soil]}।`);if(o.drainage==='slow')notes.push('পানি জমে থাকে: ভুট্টা বা বিনের আগে নিষ্কাশন ও স্থানীয় উপযোগিতা যাচাই প্রয়োজন।');else if(o.drainage==='unknown')notes.push('পানি নিষ্কাশন অজানা।');else notes.push('ভালো নিষ্কাশন: ব্যবহারকারীর দেওয়া তথ্য।');notes.push('মাটির ধরন ranking বদলায় না; শুরুর পানির ইনপুট হিসাব বদলায়। লবণাক্ততা ও pH model করা হয়নি।');$('#constraints').textContent=notes.join(' ');
$('#cards').innerHTML=comparison.map((c,i)=>`<article class="crop-card ${i===0?'first':''}"><div class="rank">${i===0?'এই অগ্রাধিকারে প্রথম':'তুলনার বিকল্প '+(i+1)}</div><h3>${c.bn}</h3><p class="sequence">আগের ফসল ধান · পরের ফসল ${c.bn}</p><div class="value">${fmt(c.gap)} <small>mm</small></div><p class="value-label">পানির হিসাবের মধ্যক ঘাটতি</p><div class="waterbar" aria-label="পানির চাহিদার হিসাবে পূরণ হয়েছে ${fmt((c.waterFit??0)*100)} শতাংশ"><span style="width:${Math.round((c.waterFit??0)*100)}%"></span></div><p class="crop-meta">পাঁচ বছরের পরিসর: ${fmt(c.minGap)}–${fmt(c.maxGap)} mm<br>ধরা চাহিদা: ${c.need} mm / ${c.days} দিন<br>মধ্যক মৌসুমি বৃষ্টি: ${fmt(c.medianRain)} mm<br>সম্পূর্ণ মৌসুম: ${c.validSeasons}/5</p></article>`).join('');
const grid=monthly(raw);$('#calendar').innerHTML='<span></span>'+short.map(m=>`<span class="cal-label">${m}</span>`).join('')+grid.map(row=>`<span class="cal-label">${row.year}</span>`+row.months.map((m,i)=>{const v=m.rain,f=v===null?0:Math.min(1,v/600),light=96-f*68;return `<button type="button" class="${i+1===o.month?'active':''}" data-month="${i+1}" style="background:hsl(153 36% ${light}%);color:${f>.6?'white':'#163c2c'}" aria-label="${row.year} ${bnMonths[i]} ${fmt(v)} mm বৃষ্টি; রোপণের মাস নির্বাচন">${v===null?'—':fmt(v)}</button>`;}).join('')).join('');renderYears();}
function renderYears(){const c=comparison.find(c=>c.id===$('#detail-crop').value);if(!c)return;$('#year-rows').innerHTML=c.seasons.map(s=>`<tr><td>${s.year}<small style="display:block;color:#667c70;font-size:12px">${s.start} / ${s.end}</small></td><td>${fmt(s.rain)} mm</td><td>${fmt(s.drySpell)} দিন</td><td>${fmt(s.hotDays)}</td><td>${fmt(s.gap)} mm</td></tr>`).join('');}
function report(){return {project:'KhetShift',generatedAt:new Date().toISOString(),purpose:'Historical scenario comparison, not a forecast or irrigation prescription',location:point,inputs:options(),method:'gap = max(0, assumed crop need - historical rain * assumed usable fraction - planned irrigation - initial soil water); median across five sowing years',ranking:'UI heuristic: water fit and cereal-to-legume preference, not validated soil-health score',limitations:['NASA gridded reanalysis, not field measurement','FAO indicative crop range; editable unvalidated duration','No daily soil balance, timing, rice seepage, salinity, pH, market or cultivar model','No field validation or outcome claim'],results:comparison};}
$('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(report(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`KhetShift-${point.id}-comparison.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('#place').addEventListener('change',load);$('#retry').addEventListener('click',load);['month','day','irrigation','soil','drainage','soilWater','priority','rainFraction'].forEach(id=>$('#'+id).addEventListener('input',render));$('#detail-crop').addEventListener('change',renderYears);$('#calendar').addEventListener('click',e=>{const b=e.target.closest('[data-month]');if(b){$('#month').value=b.dataset.month;render();}});
$('#crop-inputs').addEventListener('input',e=>{if(!e.target.dataset.crop)return;const c=crops.find(c=>c.id===e.target.dataset.crop);c[e.target.dataset.field]=Number(e.target.value);render();});
$('#assumption-reset').addEventListener('click',()=>{crops=CROPS.map(c=>({...c}));document.querySelectorAll('[data-crop]').forEach(el=>el.value=crops.find(c=>c.id===el.dataset.crop)[el.dataset.field]);$('#rainFraction').value='70';render();});
$('#reset').addEventListener('click',()=>{Object.entries({place:'bogura',month:'11',day:'15',irrigation:'200',soil:'unknown',drainage:'unknown',soilWater:'0',priority:'balanced',rainFraction:'70'}).forEach(([id,v])=>$('#'+id).value=v);crops=CROPS.map(c=>({...c}));document.querySelectorAll('[data-crop]').forEach(el=>el.value=crops.find(c=>c.id===el.dataset.crop)[el.dataset.field]);load();});
$('#language').addEventListener('click',()=>{let el=$('#english');if(el){el.remove();$('#language').textContent='English';return;}el=document.createElement('section');el.id='english';el.className='english-summary';el.lang='en';el.innerHTML='<h2>Explore the crop after rice</h2><p>KhetShift compares paddy rice, maize and an illustrative bean alternative using six years of real NASA POWER daily weather archives at four Bangladesh sample points. Select a place, planting month, irrigation budget, local soil information and priority. Results show the median scenario water gap across five sowing years, alongside every year’s rain and dry spells.</p><p>All assumptions are editable. This is a historical planning prototype, with no trained AI, field validation or yield forecast. The bean case is an exploratory alternative, not a locally validated cultivar recommendation. Download the comparison with its data source and limitations.</p>';$('.intro').after(el);$('#language').textContent='বাংলা';});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'configure_crop_comparison',title:'Configure crop comparison',description:'Update the visible historical crop comparison for a Bangladesh sample point. Does not prescribe a crop or irrigate a field.',inputSchema:{type:'object',properties:{place:{type:'string',enum:['bogura','rajshahi','khulna','sylhet']},month:{type:'integer',minimum:1,maximum:12},irrigation:{type:'number',minimum:0,maximum:1000}},required:['place','month','irrigation'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||!['bogura','rajshahi','khulna','sylhet'].includes(input.place)||!Number.isInteger(input.month)||input.month<1||input.month>12||!Number.isFinite(input.irrigation)||input.irrigation<0||input.irrigation>1000)throw Error('Invalid comparison inputs');$('#place').value=input.place;$('#month').value=String(input.month);$('#irrigation').value=String(input.irrigation);await load();if(!raw||point.id!==input.place||$('#result-body').hidden)throw Error('Data load failed');return {location:point.name,assumptions:options(),results:comparison.map(c=>({crop:c.en,medianScenarioGapMm:c.gap,completeSeasons:c.validSeasons}))};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
load();
